import json,pathlib
P=pathlib.Path('research/asia');r=json.load(open(P/'reviews.json'))
def add(id,diff,reason,sol='',topic=None,subtopics=None,**kw):
 r[id]={'difficulty':diff,'reason':reason,'proofConfidence':'checked' if diff is not None else 'unresolved',**kw}
 if sol:r[id]['solutionOverride']=sol
 if topic:r[id]['topic']=topic
 if subtopics:r[id]['subtopics']=subtopics;r[id]['tags']=subtopics
add('chn_2012_d9329f',4,'The circumcentre of BCI is the midpoint of arc BC opposite A; recognising that standard incenter lemma makes reflection across AI finish the problem.',r'''Let $L$ be the midpoint of the arc $BC$ not containing $A$ in the circumcircle of $ABC$. The line $AL$ is the internal angle bisector, so $A,I,L$ are collinear. The usual angle-bisector arc lemma gives $LB=LC=LI$: for instance, $\angle LBI=(A+B)/2=\angle BIL$, and similarly for $C$. Thus $L$ is the circumcentre of $BCI$, namely $O$. Reflection in $AI$ fixes $O$, exchanges the incircle contact points $D,E$, and carries the ray $DB$ to the ray $EC$. It therefore carries $\angle ODB$ to $\angle OEC$, proving equality.''',topic='Geometry',subtopics=['Triangle centres','Angles & cyclic quadrilaterals','Transformations'])
add('chn_2012_faca65',6.5,'Several cyclic quadrilaterals identify an orthocentre and an angle bisector; the bisector ratio is then matched to two secant-power products.',r'''Tangency gives $I,D,E,B$ concyclic. Since $DF\perp AI$ and the tangent-chord theorem gives $\angle MED=\angle FDA$, the points $I,D,E,M$ are also concyclic. Hence $BM\perp AI$. Similarly $AN\perp BI$. Let $G=BM\cap AN$. Then $I$ is the orthocentre of $GAB$, so $G,I,D$ are collinear. The right angles imply $G,N,D,B$ and $G,M,D,A$ are cyclic. Their angle relations show that $DI$ bisects one of the angles between $DM$ and $DN$. The internal or external angle-bisector theorem, in ordinary positive lengths, gives $DM/DN=KM/KN$.

Finally, the two circles $IDEM$ and $IDFN$ give, by secant power from $K$, $KM\cdot KE=KI\cdot KD=KN\cdot KF$ (or the corresponding directed products). Therefore $DM/DN=KF/KE$, and the required product identity follows.''',topic='Geometry',subtopics=['Angles & cyclic quadrilaterals','Triangle centres','Power of a point & radical axes'],note='Incircle “intersects” was interpreted as tangency; directed secant products handle the possible external positions.')
